    const defs = [[boatBarge(0), -150, -260, 2.6], [boatBarge(1), -300, 240, -2.1], [boatBarge(2), -225, -40, 1.7], [boatFerry(), -345, 60, -3.6]]; let nl = 0;
    for (const [b, x, z, v] of defs) { b.g.position.set(x, WY + .9, z); b.g.rotation.y = v < 0 ? PI : 0; scene.add(b.g); b.x = x; b.z = z; b.v = v; b.i0 = nl; nl += b.lights.length; S.boats.push(b); b.g.traverse(o => { if (o.isMesh && (o.material === M.win || o.material === M.palG)) S.nightMeshes.push(o); }); }
    // bridge traffic + nav lights as one instanced mesh
