      if (!ok && env.skyColor && env.horizonColor) { U.uSkyZ.value.copy(env.skyColor); U.uSkyH.value.copy(env.horizonColor); U.uSkyS.value.copy(env.horizonColor).multiplyScalar(1.4); }
